 59→// --- Transcript Storage ---
 60→
 61→// ReadTranscript reads the cached transcript JSON for a session.
 62→func (k *KiroAgent) ReadTranscript(sessionRef string) ([]byte, error) {
 63→	data, err := os.ReadFile(sessionRef) //nolint:gosec // Path from agent hook
 64→	if err != nil {
 65→		return nil, fmt.Errorf("failed to read transcript: %w", err)
 66→	}
 67→	return data, nil
 68→}
 69→
 70→// ChunkTranscript splits a JSON transcript into chunks.
 71→// Kiro transcripts are single JSON objects; we use the JSONL chunker since the
 72→// cached format is a JSON blob that fits in a single chunk in most cases.
 73→func (k *KiroAgent) ChunkTranscript(_ context.Context, content []byte, maxSize int) ([][]byte, error) {
 74→	if len(content) <= maxSize {
 75→		return [][]byte{content}, nil
 76→	}
 77→	// For large transcripts, split at line boundaries
 78→	chunks, err := agent.ChunkJSONL(content, maxSize)
 79→	if err != nil {
 80→		return nil, fmt.Errorf("failed to chunk transcript: %w", err)
 81→	}
 82→	return chunks, nil
 83→}
 84→
 85→// ReassembleTranscript combines transcript chunks back into a single blob.
 86→func (k *KiroAgent) ReassembleTranscript(chunks [][]byte) ([]byte, error) {
 87→	if len(chunks) == 1 {
 88→		return chunks[0], nil
 89→	}
 90→	return agent.ReassembleJSONL(chunks), nil
 91→}
