111→// ReadSession reads session data from the cached transcript.
112→func (k *KiroAgent) ReadSession(input *agent.HookInput) (*agent.AgentSession, error) {
113→	if input.SessionRef == "" {
114→		return nil, errors.New("session reference (transcript path) is required")
115→	}
116→
117→	data, err := os.ReadFile(input.SessionRef)
118→	if err != nil {
119→		return nil, fmt.Errorf("failed to read transcript: %w", err)
120→	}
121→
122→	return &agent.AgentSession{
123→		SessionID:  input.SessionID,
124→		AgentName:  k.Name(),
125→		SessionRef: input.SessionRef,
126→		StartTime:  time.Now(),
127→		NativeData: data,
128→	}, nil
129→}
