131→// WriteSession writes session data for resumption.
132→func (k *KiroAgent) WriteSession(_ context.Context, session *agent.AgentSession) error {
133→	if session == nil {
134→		return errors.New("session is nil")
135→	}
136→	if session.AgentName != "" && session.AgentName != k.Name() {
137→		return fmt.Errorf("session belongs to agent %q, not %q", session.AgentName, k.Name())
138→	}
139→	if session.SessionRef == "" {
140→		return errors.New("session reference (transcript path) is required")
141→	}
142→	if len(session.NativeData) == 0 {
143→		return errors.New("session has no native data to write")
144→	}
145→
146→	if err := os.MkdirAll(filepath.Dir(session.SessionRef), 0o750); err != nil {
147→		return fmt.Errorf("failed to create session dir: %w", err)
148→	}
149→
150→	if err := os.WriteFile(session.SessionRef, session.NativeData, 0o600); err != nil {
151→		return fmt.Errorf("failed to write transcript: %w", err)
152→	}
153→	return nil
154→}
