168→// GetTranscriptPosition returns the number of history entries in a Kiro transcript.
169→// Kiro uses JSON format with paired user+assistant history entries, so position
170→// is the entry count. Returns 0 if the file doesn't exist, is empty, or is a
171→// placeholder "{}".
172→func (k *KiroAgent) GetTranscriptPosition(path string) (int, error) {
173→	if path == "" {
174→		return 0, nil
175→	}
176→
177→	data, err := os.ReadFile(path) //nolint:gosec // Reading from controlled transcript path
178→	if err != nil {
179→		if os.IsNotExist(err) {
180→			return 0, nil
181→		}
182→		return 0, fmt.Errorf("failed to read transcript: %w", err)
183→	}
184→
185→	if len(data) == 0 {
186→		return 0, nil
187→	}
188→
189→	t, err := parseTranscript(data)
190→	if err != nil {
191→		return 0, fmt.Errorf("failed to parse transcript: %w", err)
192→	}
193→
194→	return len(t.History), nil
195→}
