197→// ExtractModifiedFilesFromOffset extracts files modified since a given history index.
198→// For Kiro (JSON format), offset is the starting history entry index.
199→func (k *KiroAgent) ExtractModifiedFilesFromOffset(path string, startOffset int) (files []string, currentPosition int, err error) {
200→	if path == "" {
201→		return nil, 0, nil
202→	}
203→
204→	data, readErr := os.ReadFile(path) //nolint:gosec // Reading from controlled transcript path
205→	if readErr != nil {
206→		if os.IsNotExist(readErr) {
207→			return nil, 0, nil
208→		}
209→		return nil, 0, fmt.Errorf("failed to read transcript: %w", readErr)
210→	}
211→
212→	if len(data) == 0 {
213→		return nil, 0, nil
214→	}
215→
216→	t, parseErr := parseTranscript(data)
217→	if parseErr != nil {
218→		return nil, 0, parseErr
219→	}
220→
221→	totalEntries := len(t.History)
222→
223→	if startOffset >= totalEntries {
224→		return nil, totalEntries, nil
225→	}
226→
227→	modifiedFiles := extractModifiedFilesFromHistory(t.History[startOffset:])
228→	return modifiedFiles, totalEntries, nil
229→}
