231→// ExtractPrompts extracts user prompts from the transcript starting at the given offset.
232→// Only Prompt-type user messages are returned; ToolUseResults entries are skipped.
233→func (k *KiroAgent) ExtractPrompts(sessionRef string, fromOffset int) ([]string, error) {
234→	data, err := os.ReadFile(sessionRef) //nolint:gosec // Path comes from agent hook input
235→	if err != nil {
236→		return nil, fmt.Errorf("failed to read transcript: %w", err)
237→	}
238→
239→	t, parseErr := parseTranscript(data)
240→	if parseErr != nil {
241→		return nil, fmt.Errorf("failed to parse transcript: %w", parseErr)
242→	}
243→
244→	var prompts []string
245→	for i := fromOffset; i < len(t.History); i++ {
246→		if prompt := extractUserPrompt(t.History[i].User.Content); prompt != "" {
247→			prompts = append(prompts, prompt)
