268→// --- SQLite helpers ---
269→
270→// escapeSQLString escapes single quotes for use in SQLite string literals.
271→func escapeSQLString(s string) string {
272→	return strings.ReplaceAll(s, "'", "''")
273→}
274→
275→// --- SQLite session resolution ---
276→
277→// dbPath returns the path to Kiro's SQLite database.
278→func dbPath() (string, error) {
279→	home, err := os.UserHomeDir()
280→	if err != nil {
281→		return "", fmt.Errorf("failed to get home directory: %w", err)
282→	}
283→	switch runtime.GOOS {
284→	case "darwin":
285→		return filepath.Join(home, "Library", "Application Support", "kiro-cli", "data.sqlite3"), nil
286→	default: // linux
287→		return filepath.Join(home, ".local", "share", "kiro-cli", "data.sqlite3"), nil
288→	}
289→}
290→
291→// querySessionID queries the SQLite database for the most recent conversation ID
292→// associated with the given CWD.
293→func (k *KiroAgent) querySessionID(ctx context.Context, cwd string) (string, error) {
294→	if os.Getenv("ENTIRE_TEST_KIRO_MOCK_DB") == "1" {
295→		return "mock-session-id", nil
296→	}
297→
298→	db, err := dbPath()
299→	if err != nil {
300→		return "", err
301→	}
302→	if _, err := os.Stat(db); err != nil {
303→		return "", fmt.Errorf("kiro database not found at %s: %w", db, err)
304→	}
305→
306→	query := fmt.Sprintf(
307→		"SELECT json_extract(value, '$.conversation_id') FROM conversations_v2 WHERE key = '%s' ORDER BY updated_at DESC LIMIT 1",
308→		escapeSQLString(cwd),
309→	)
310→
311→	cmd := exec.CommandContext(ctx, "sqlite3", "-json", db, query)
312→	out, err := cmd.Output()
313→	if err != nil {
314→		logging.Warn(ctx, "kiro: sqlite3 query failed", "err", err, "cwd", cwd)
315→		return "", fmt.Errorf("sqlite3 query failed: %w", err)
316→	}
317→
318→	result := strings.TrimSpace(string(out))
319→	if result == "" || result == "[]" {
320→		return "", nil
321→	}
322→
323→	// sqlite3 -json returns an array of objects
324→	var rows []map[string]string
325→	if err := json.Unmarshal([]byte(result), &rows); err != nil {
326→		return "", fmt.Errorf("failed to parse sqlite3 output: %w", err)
327→	}
328→	if len(rows) == 0 {
329→		return "", nil
330→	}
331→
332→	// The column name from json_extract
333→	for _, v := range rows[0] {
334→		return v, nil
335→	}
336→	return "", nil
337→}
338→
339→// ensureCachedTranscript fetches the conversation from SQLite and caches it
340→// to .entire/tmp/<sessionID>.json. Returns the cache file path.
341→func (k *KiroAgent) ensureCachedTranscript(ctx context.Context, cwd, sessionID string) (string, error) {
342→	repoRoot, err := paths.WorktreeRoot(ctx)
343→	if err != nil {
344→		repoRoot = cwd
345→	}
346→
347→	cacheDir := filepath.Join(repoRoot, ".entire", "tmp")
348→	cachePath := filepath.Join(cacheDir, sessionID+".json")
349→
350→	// Fetch fresh transcript from SQLite on every call (transcript grows during session)
351→	if os.Getenv("ENTIRE_TEST_KIRO_MOCK_DB") == "1" {
352→		// In test mode, return the expected cache path without hitting SQLite.
353→		return cachePath, nil
354→	}
355→
356→	db, err := dbPath()
357→	if err != nil {
358→		return "", err
359→	}
360→
361→	query := fmt.Sprintf(
362→		"SELECT value FROM conversations_v2 WHERE key = '%s' ORDER BY updated_at DESC LIMIT 1",
363→		escapeSQLString(cwd),
364→	)
365→
366→	cmd := exec.CommandContext(ctx, "sqlite3", db, query)
367→	out, err := cmd.Output()
368→	if err != nil {
369→		return "", fmt.Errorf("sqlite3 transcript query failed: %w", err)
370→	}
371→
372→	transcript := strings.TrimSpace(string(out))
373→	if transcript == "" {
374→		return "", errors.New("no transcript found")
375→	}
376→
377→	if err := os.MkdirAll(cacheDir, 0o750); err != nil {
378→		return "", fmt.Errorf("failed to create cache dir: %w", err)
379→	}
380→
381→	if err := os.WriteFile(cachePath, []byte(transcript), 0o600); err != nil {
382→		return "", fmt.Errorf("failed to write cached transcript: %w", err)
383→	}
384→
385→	return cachePath, nil
386→}
