388→// --- IDE transcript discovery ---
389→
390→// ideWorkspaceSessionsDir returns the directory where the Kiro IDE stores
391→// session files for the given working directory. The directory is derived from
392→// the base64-encoded CWD.
393→func ideWorkspaceSessionsDir(cwd string) (string, error) {
394→	home, err := os.UserHomeDir()
395→	if err != nil {
396→		return "", fmt.Errorf("failed to get home directory: %w", err)
397→	}
398→
399→	encoded := base64.StdEncoding.EncodeToString([]byte(cwd))
400→
401→	var baseDir string
402→	switch runtime.GOOS {
403→	case "darwin":
404→		baseDir = filepath.Join(home, "Library", "Application Support", "Kiro", "User", "globalStorage", "kiro.kiroagent", "workspace-sessions")
405→	default: // linux
406→		baseDir = filepath.Join(home, ".config", "Kiro", "User", "globalStorage", "kiro.kiroagent", "workspace-sessions")
407→	}
408→
409→	return filepath.Join(baseDir, encoded), nil
410→}
411→
412→// ensureIDETranscript looks for the most recent Kiro IDE session transcript
413→// for the given CWD and copies it to .entire/tmp/<sessionID>.json.
414→// Returns the cache path on success, or empty string if no transcript is found.
415→func (k *KiroAgent) ensureIDETranscript(ctx context.Context, cwd, sessionID string) (string, error) {
416→	sessDir, err := ideWorkspaceSessionsDir(cwd)
417→	if err != nil {
418→		return "", err
419→	}
420→
421→	// Read the sessions.json index.
422→	indexPath := filepath.Join(sessDir, "sessions.json")
423→	indexData, err := os.ReadFile(indexPath) //nolint:gosec // Controlled path from IDE storage
424→	if err != nil {
425→		logging.Debug(ctx, "kiro: IDE sessions.json not found", "path", indexPath, "err", err)
426→		return "", fmt.Errorf("IDE sessions.json not found: %w", err)
427→	}
428→
429→	var sessions []kiroIDESessionEntry
430→	if err := json.Unmarshal(indexData, &sessions); err != nil {
431→		return "", fmt.Errorf("failed to parse IDE sessions.json: %w", err)
432→	}
433→
434→	if len(sessions) == 0 {
435→		return "", errors.New("no IDE sessions found")
436→	}
437→
438→	// Sort by dateCreated descending to find the most recent session.
439→	sort.Slice(sessions, func(i, j int) bool {
440→		return sessions[i].DateCreated > sessions[j].DateCreated
441→	})
442→
443→	// Read the most recent session's transcript.
444→	latestSession := sessions[0]
445→	transcriptPath := filepath.Join(sessDir, latestSession.SessionID+".json")
446→	transcriptData, err := os.ReadFile(transcriptPath) //nolint:gosec // Controlled path from IDE storage
447→	if err != nil {
448→		return "", fmt.Errorf("failed to read IDE transcript %s: %w", transcriptPath, err)
449→	}
450→
451→	// Cache the transcript under our session ID.
452→	repoRoot, rootErr := paths.WorktreeRoot(ctx)
453→	if rootErr != nil {
454→		repoRoot = cwd
455→	}
456→
457→	cacheDir := filepath.Join(repoRoot, ".entire", "tmp")
458→	cachePath := filepath.Join(cacheDir, sessionID+".json")
459→
460→	if err := os.MkdirAll(cacheDir, 0o750); err != nil {
461→		return "", fmt.Errorf("failed to create cache dir: %w", err)
462→	}
463→
464→	if err := os.WriteFile(cachePath, transcriptData, 0o600); err != nil {
465→		return "", fmt.Errorf("failed to write cached IDE transcript: %w", err)
466→	}
467→
468→	logging.Info(ctx, "kiro: cached IDE transcript",
469→		"ide_session", latestSession.SessionID,
470→		"our_session", sessionID,
471→		"cache_path", cachePath,
472→	)
473→
474→	return cachePath, nil
475→}
