 53→// ideHookDefs lists the 4 IDE hook files to install.
 54→// No agentSpawn IDE hook — the IDE has no such trigger.
 55→// The first promptSubmit serves as session start.
 56→var ideHookDefs = []ideHookDef{
 57→	{Filename: "entire-prompt-submit", TriggerType: "promptSubmit", CLIVerb: HookNameUserPromptSubmit},
 58→	{Filename: "entire-stop", TriggerType: "agentStop", CLIVerb: HookNameStop},
 59→	{Filename: "entire-pre-tool-use", TriggerType: "preToolUse", CLIVerb: HookNamePreToolUse},
