 63→// InstallHooks installs Entire hooks in .kiro/agents/entire.json (CLI hooks)
 64→// and .kiro/hooks/*.kiro.hook (IDE hooks).
 65→// Returns the total number of hooks installed (CLI + IDE).
 66→func (k *KiroAgent) InstallHooks(ctx context.Context, localDev bool, force bool) (int, error) {
 67→	worktreeRoot, err := paths.WorktreeRoot(ctx)
 68→	if err != nil {
 69→		worktreeRoot = "."
 70→	}
 71→
 72→	hooksPath := filepath.Join(worktreeRoot, ".kiro", hooksDir, HooksFileName)
 73→
 74→	// If hooks are already installed and not forcing, check if they're current
 75→	if !force {
 76→		if existing, readErr := os.ReadFile(hooksPath); readErr == nil { //nolint:gosec // path constructed from repo root
 77→			var file kiroAgentFile
 78→			if json.Unmarshal(existing, &file) == nil && allHooksPresent(file.Hooks, localDev) && allIDEHooksPresent(worktreeRoot, localDev) {
 79→				return 0, nil
 80→			}
 81→		}
 82→	}
 83→
 84→	var cmdPrefix string
 85→	if localDev {
 86→		cmdPrefix = localDevCmdPrefix + "hooks kiro "
 87→	} else {
 88→		cmdPrefix = prodHookCmdPrefix
 89→	}
 90→
 91→	file := kiroAgentFile{
 92→		Name: "entire",
 93→		// Include all default Kiro tools so the agent profile doesn't restrict them.
 94→		Tools: []string{
 95→			"read", "write", "shell", "grep", "glob",
 96→			"aws", "report", "introspect", "knowledge",
 97→			"thinking", "todo", "delegate",
 98→		},
 99→		Hooks: kiroHooks{
100→			AgentSpawn:       []kiroHookEntry{{Command: cmdPrefix + HookNameAgentSpawn}},
101→			UserPromptSubmit: []kiroHookEntry{{Command: cmdPrefix + HookNameUserPromptSubmit}},
102→			PreToolUse:       []kiroHookEntry{{Command: cmdPrefix + HookNamePreToolUse}},
103→			PostToolUse:      []kiroHookEntry{{Command: cmdPrefix + HookNamePostToolUse}},
104→			Stop:             []kiroHookEntry{{Command: cmdPrefix + HookNameStop}},
105→		},
106→	}
107→
108→	if err := os.MkdirAll(filepath.Dir(hooksPath), 0o750); err != nil {
109→		return 0, fmt.Errorf("failed to create .kiro/agents directory: %w", err)
110→	}
111→
112→	output, err := jsonutil.MarshalIndentWithNewline(file, "", "  ")
113→	if err != nil {
114→		return 0, fmt.Errorf("failed to marshal hooks config: %w", err)
115→	}
116→
117→	if err := os.WriteFile(hooksPath, output, 0o600); err != nil {
118→		return 0, fmt.Errorf("failed to write hooks config: %w", err)
119→	}
120→
121→	// Install IDE hooks (.kiro/hooks/*.kiro.hook)
